changeSet.sql:
DO $$
DECLARE
orphan_count integer;
BEGIN
UPDATE hts_ict_contact c
SET facility_id = e.facility_id
    FROM hts_ict_encounter e
WHERE c.ict_encounter_id = e.id
  AND c.facility_id IS NULL;

SELECT COUNT(*) INTO orphan_count
FROM hts_ict_contact
WHERE facility_id IS NULL;

IF orphan_count = 0 THEN
ALTER TABLE hts_ict_contact ALTER COLUMN facility_id SET NOT NULL;
ELSE
        RAISE NOTICE 'hts_ict_contact: % row(s) could not be backfilled (no matching hts_ict_encounter) and were left with facility_id = NULL. NOT NULL constraint was skipped.', orphan_count;
END IF;
END $$;
